import{_ as a,a as n,b as p}from"./chunks/mmad_nongemv_compare.DFnisJ3M.js";import{_ as l,o as c,a as e,b as t}from"./app.BAU4IqPF.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（Tensor API，试验特性）","link":"/api/SIMD-API/basic_api/cube_compute_TensorAPI/cube_compute_TensorAPI"},{"text":"Mmad计算关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_TensorAPI/mmad_compute_key_features/mmad_compute_key_features"},{"text":"GEMV","link":"/api/SIMD-API/basic_api/cube_compute_TensorAPI/mmad_compute_key_features/GEMV"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_TensorAPI/mmad_compute_key_features/GEMV.md","filePath":"api/SIMD-API/basic_api/cube_compute_TensorAPI/mmad_compute_key_features/GEMV.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用优势","slug":"使用优势","link":"#使用优势"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1785832713000}'),o={name:"api/SIMD-API/basic_api/cube_compute_TensorAPI/mmad_compute_key_features/GEMV.md"};function r(w,s,i,d,m,_){return c(),e("div",null,[...s[0]||(s[0]=[t('<div><article class="markdown-body"><h1>GEMV</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>GEMV的核心功能体现为：当矩阵A的维度M取值为1时，接口可以手动启用GEMV功能，该操作退化为1×K维度的行向量与K×N维度矩阵之间的乘法运算。</p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT产品，GEMV模式默认关闭。如需启用GEMV模式，需要设置<code>MmadTrait::disableGemv</code>参数为<code>false</code>。</p></div><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li><p>1×K矩阵A需满足512B地址对齐，K个数据连续存储。以<code>half</code>类型为例，当K=256时，软件侧可视作16×16分块，配置m=1后硬件解析为1×256向量，可通过<code>Copy</code>接口将256个<code>half</code>数据从L1 Buffer搬至L0A Buffer。</p></li><li><p>C矩阵是一个1×N的向量，当1×N向量被划分为多个1×16子向量时，每个子向量在L0C Buffer中占用1024B。但实际有效数据仅占最低32B或64B。例如，当N=50时，共划分4个1×16子向量，占用4×512B=2048B，其中有效数据仅为4×32B=128B。</p></li></ul><p><strong>图1</strong> GEMV模式矩阵乘示意图</p><p><img src="'+a+'" alt="GEMV模式矩阵乘示意图"></p><h2 id="使用优势">使用优势<a class="header-anchor" href="#使用优势">​</a></h2><p>M=1时开启GEMV模式，则矩阵乘法将M方向作为非对齐场景进行处理。GEMV模式相较于非对齐处理方式，搬运数据量更少，性能更好。下面以M=1、K=256、N=32，左右矩阵数据类型为<code>half</code>的矩阵乘示例说明。</p><ul><li><p>GEMV模式</p><p>将A矩阵从L1 Buffer搬运到L0A Buffer时，1×256的向量被当作16×16的矩阵进行处理，调用<code>Copy</code>接口一次完成16×16分形大小的矩阵搬运。B矩阵的搬运以及矩阵乘计算跟基础场景相同，如下图所示。</p><p><strong>图2</strong> GEMV模式M=1的矩阵乘计算示意图</p><p><img src="'+n+'" alt="GEMV模式M=1的矩阵乘计算示意图"></p></li><li><p>非GEMV模式</p><p>将A矩阵从L1 Buffer搬运到L0A Buffer时，1×256的向量被当作非对齐矩阵数据进行处理，将M方向对齐到32字节后进行搬运。调用<code>Copy</code>接口每次搬运16×16分形大小的矩阵，一共搬运K/16=16次，导致搬运数据量增加，性能相较于GEMV模式差，如下图所示。</p><p><strong>图3</strong> 非GEMV模式M不等于1的矩阵乘计算示意图</p><p><img src="'+p+`" alt="非GEMV模式M不等于1的矩阵乘计算示意图"></p></li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>本GEMV场景示例的规格如下：</p><table><thead><tr><th>矩阵</th><th>维度大小</th><th>数据类型</th><th>格式</th></tr></thead><tbody><tr><td>A</td><td>1×4096</td><td>half</td><td>ND</td></tr><tr><td>B</td><td>4096×256</td><td>half</td><td>NZ</td></tr><tr><td>C</td><td>1×256</td><td>float</td><td>ND</td></tr></tbody></table><p>通过<a href="../cube_compute_load/Copy_GMToL1.html">Copy</a>接口将输入矩阵A从Global Memory搬运到L1 Buffer上并保持ND格式不变，然后在L1 Buffer上将A矩阵转换为NZ格式，再通过<a href="../cube_compute_load/Copy_L1ToL0A.html">Copy</a>接口搬运到L0A Buffer，从而以GEMV模式执行矩阵乘。另外注意GEMV模式默认是关闭的，需要自定义<a href="../mmad_compute/Mmad.html">MmadTrait</a>来开启。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">AscendC</span><span class="o">::</span><span class="nn">Te</span><span class="p">;</span>

<span class="k">struct</span><span class="w"> </span><span class="nc">MmadTraitCustom</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="n">TraitType</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MmadTrait</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 设置MmadTrait::disableGemv参数为false，开启GEMV。</span>
<span class="w">    </span><span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">TraitType</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MmadTrait</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="n">MmadType</span><span class="o">::</span><span class="n">NORMAL</span><span class="p">);</span>
<span class="p">};</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">MmadGemvExample</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">aGm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">bGm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">cGm</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="n">AType</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">half</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4096</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 数据类型half的C0_ELEMENT = C0_SIZE(32B) / sizeof(half) = 16，1×K向量按NZ格式重排为(K/C0_ELEMENT)×C0_ELEMENT大小的Tensor。</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">c0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">C0_ELEMENT</span><span class="o">&lt;</span><span class="n">AType</span><span class="o">&gt;</span><span class="p">;</span>

<span class="w">    </span><span class="n">__cbuf__</span><span class="w"> </span><span class="n">AType</span><span class="w"> </span><span class="n">l1ABuf</span><span class="p">[</span><span class="n">m</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">k</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ca__</span><span class="w"> </span><span class="n">AType</span><span class="w"> </span><span class="n">l0ABuf</span><span class="p">[</span><span class="n">m</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">k</span><span class="p">];</span>

<span class="w">    </span><span class="c1">// A矩阵Global Memory-&gt;L1 Buffer：ND-&gt;ND，1×K行向量按ND连续搬入L1 Buffer。</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">gmATensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">MakeMemPtr</span><span class="p">(</span><span class="n">aGm</span><span class="p">),</span><span class="w"> </span><span class="n">MakeFrameLayout</span><span class="o">&lt;</span><span class="n">NDExtLayoutPtn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l1ATensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">MakeMemPtr</span><span class="p">(</span><span class="n">l1ABuf</span><span class="p">),</span><span class="w"> </span><span class="n">MakeFrameLayout</span><span class="o">&lt;</span><span class="n">NDExtLayoutPtn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">copyGm2L1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeCopy</span><span class="p">(</span><span class="n">CopyGM2L1</span><span class="p">{},</span><span class="w"> </span><span class="n">CopyGM2L1TraitDefault</span><span class="p">{});</span>
<span class="w">    </span><span class="n">Copy</span><span class="p">(</span><span class="n">copyGm2L1</span><span class="p">,</span><span class="w"> </span><span class="n">l1ATensor</span><span class="p">,</span><span class="w"> </span><span class="n">gmATensor</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 在L1 Buffer上把这块连续数据重新解释为(K/C0_ELEMENT)×C0_ELEMENT大小的NZ分形矩阵（地址不变，仅换Layout）。</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l1ANzTensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">l1ATensor</span><span class="p">.</span><span class="n">Data</span><span class="p">(),</span><span class="w"> </span><span class="n">MakeFrameLayout</span><span class="o">&lt;</span><span class="n">NZLayoutPtn</span><span class="p">,</span><span class="w"> </span><span class="n">AType</span><span class="o">&gt;</span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">c0</span><span class="p">,</span><span class="w"> </span><span class="n">c0</span><span class="p">));</span>
<span class="w">    </span><span class="c1">// L1 Buffer-&gt;L0A Buffer：NZ-&gt;NZ非转置搬运，一次完成分形搬运。</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l0ATensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">MakeMemPtr</span><span class="p">(</span><span class="n">l0ABuf</span><span class="p">),</span><span class="w"> </span><span class="n">MakeFrameLayout</span><span class="o">&lt;</span><span class="n">NZLayoutPtn</span><span class="p">,</span><span class="w"> </span><span class="n">AType</span><span class="o">&gt;</span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">c0</span><span class="p">,</span><span class="w"> </span><span class="n">c0</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">copyL12L0A</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeCopy</span><span class="p">(</span><span class="n">CopyL12L0A</span><span class="p">{},</span><span class="w"> </span><span class="n">CopyL12L0ATraitDefault</span><span class="p">{});</span>
<span class="w">    </span><span class="n">Copy</span><span class="p">(</span><span class="n">copyL12L0A</span><span class="p">,</span><span class="w"> </span><span class="n">l0ATensor</span><span class="p">,</span><span class="w"> </span><span class="n">l1ANzTensor</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// B矩阵搬运与基础场景相同（此处省略，假设已得到l0B）。</span>
<span class="w">    </span><span class="c1">// ...</span>

<span class="w">    </span><span class="c1">// Mmad计算：使用配置GEMV模式的Trait。</span>
<span class="w">    </span><span class="n">MmadParams</span><span class="w"> </span><span class="nf">params</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMmad</span><span class="p">(</span><span class="n">MmadOperation</span><span class="p">{},</span><span class="w"> </span><span class="n">MmadTraitCustom</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">params</span><span class="p">);</span>
<span class="w">    </span><span class="n">Mmad</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">l0C</span><span class="p">,</span><span class="w"> </span><span class="n">l0ATensor</span><span class="p">,</span><span class="w"> </span><span class="n">l0B</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const h=l(o,[["render",r]]);export{f as __pageData,h as default};
